using System;using System.Collections.Generic;using System.Diagnostics;using System.IO;using System.Linq;using System.Text;using System.Windows;using System.Windows.Automation;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Threading;
namespace SeraphimLuxury {
 static class ToolsTests {
  static void Check(bool value,string text){if(!value)throw new Exception(text);}
  internal static IEnumerable<DependencyObject> Descend(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var child in Descend(VisualTreeHelper.GetChild(o,i)))yield return child;}
  public static int Run(string directory){Directory.CreateDirectory(directory);var application=new Application {ShutdownMode=ShutdownMode.OnExplicitShutdown};var prefs=Preferences.Defaults();prefs.Premium=true;prefs.ReducedMotion=true;var store=new PreferenceStore(Path.Combine(directory,"preferences.json"));store.Save(prefs);var w=new MainWindow(store,true){Opacity=0,ShowInTaskbar=false};application.MainWindow=w;int stage=0;Process worker=null;var log=new StringBuilder();var timer=new DispatcherTimer {Interval=TimeSpan.FromMilliseconds(220)};
   timer.Tick+=delegate {try{switch(stage++){
    case 0:
      w.countryDisclosure.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));w.visibleCountries.UpdateLayout();w.UpdateLayout();Check(w.visibleCountries.Items.Count==241,"Tous les pays doivent être visibles dans le catalogue");Check(Descend(w.visibleCountries).OfType<TextBlock>().Any(t=>t.Text.Length>2),"Le catalogue doit afficher les noms, et pas des lignes vides");Check(AtlasData.Year(0)==0,"Origine symbolique à 0");Check(AtlasPlaces.Data.chapters.All(c=>c.asset.StartsWith("real-")&&c.panel==-1&&c.imageSource.StartsWith("https://commons.wikimedia.org/")),"Images documentaires, sources et cadrage complet");Check(AtlasPlaces.Data.horizons.Count==0,"Pas de paysages fictifs sur les lieux non documentés");Check(w.HomeNav.Any(b=>(string)b.Tag=="Checklist"),"Navigation Checklist");w.countriesPopup13.IsOpen=false;w.Capture(Path.Combine(directory,"home.png"));w.ToolsWorker(directory,out worker);log.AppendLine("PASS catalogue visible, origine 0, archives réelles, suppression des paysages inventés, checklist.");break;
    case 1:w.ToolsHold();Check(w.PassageInput!=null&&!w.PassageConfirm.IsEnabled,"La nouvelle ouverture Windows doit déclencher un passage");w.PassageInput.Text="Texte erroné";Check(!w.PassageConfirm.IsEnabled,"Une phrase erronée ne valide pas");w.PassageInput.Text=w.CurrentPassage.Text;Check(w.PassageConfirm.IsEnabled,"La phrase entière valide");w.Capture(Path.Combine(directory,"passage.png"));w.PassageConfirm.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(w.ToolsHeld==0,"La validation reprend réellement le logiciel");w.ToolsExpire();w.ToolsHold();Check(w.ToolsHeld==1,"Le verrouillage strict se réapplique à expiration du passage");w.ToolsDualLayer();w.Deactivate();Check(w.ToolsHeld==0,"Désactivation libère le processus");File.WriteAllText(Path.Combine(directory,"worker.release"),"");Check(worker.WaitForExit(3000),"Le processus reprend après désactivation");log.AppendLine("PASS pause réelle d’un logiciel social de test, recopie exacte, reprise, expiration, checklist de travail non contournable et libération en veille.");w.ToolsCalendarEditor();break;
    case 2:
      var inputs=Descend(w.ToolsOverlay).OfType<TextBox>().ToArray();var name=inputs.Single(t=>AutomationProperties.GetName(t)=="Titre du rendez-vous");name.Text="Rendez-vous de test";inputs.Single(t=>AutomationProperties.GetName(t)=="Heure du rendez-vous").Text=DateTime.Now.ToString("HH:mm");Descend(w.ToolsOverlay).OfType<CheckBox>().Single().IsChecked=true;Descend(w.ToolsOverlay).OfType<Button>().Single(b=>AutomationProperties.GetName(b)=="Enregistrer").RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(store.Load().Calendar.Count==1&&store.Load().Calendar[0].Annual,"Le formulaire enregistre un rendez-vous annuel");w.Capture(Path.Combine(directory,"calendar.png"));w.ToolsCalendarTick(false);Check(!w.ToolsNotification,"Aucun rappel en veille");w.ToolsCalendarTick(true);Check(w.ToolsNotification,"Le rappel du calendrier apparaît en session active");break;
    case 3:w.ToolsNotificationCheck(Path.Combine(directory,"calendar-notification.png"));Check(w.CurrentPage=="Calendrier","Le rappel ouvre le calendrier");w.ToolsCalendarTick(true);Check(!w.ToolsNotification,"Pas de rappel dupliqué");w.ToolsClockTick();Check(w.ToolsNotification,"Un repère de trois heures déclenche un rappel");w.ToolsNotificationClose();w.ToolsClockTickAgain();Check(!w.ToolsNotification,"Un même repère ne se répète pas");log.AppendLine("PASS formulaire calendrier, persistance annuelle, rappel en bas à droite, lien vers calendrier, déduplication et repère de trois heures.");w.ShowPage("Réglages");w.Capture(Path.Combine(directory,"settings.png"));var adult=Descend(w.ToolsPage).OfType<CheckBox>().Single(c=>AutomationProperties.GetName(c)=="Contenus sensibles / 18+");adult.IsChecked=false;Check(w.ToolsAdult&&w.PassageConfirm!=null,"Retirer une protection active demande un passage");w.PassageInput.Text=w.CurrentPassage.Text;w.PassageConfirm.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Check(!store.Load().AdultFilter,"Le choix validé est réellement enregistré");w.ShowPage("Applications");w.Capture(Path.Combine(directory,"applications.png"));break;
    case 4:
      w.ToolsUsageCheck();var a=AccountSession.Create("Profil de test","Test-local-password-2026",Path.Combine(directory,"account.json"));a.Avatar="avatar.png";File.WriteAllText(Path.Combine(directory,"account.json"),Json.Write(a));Check(AccountSession.Verify(AccountSession.Load(Path.Combine(directory,"account.json")),"Test-local-password-2026"),"La photo ne doit pas corrompre l’authentification du profil");var at=new CalendarEntry {Id="leap",Title="Annuel",Date="2024-02-29",Time="09:00",Annual=true};Check(TimeRules.Due(at,new DateTime(2028,2,29,9,0,0))&&!TimeRules.Due(at,new DateTime(2027,2,28,9,0,0)),"La récurrence annuelle respecte les dates réelles");Check(Planning.Reminders(new DailyPlan {Date=Planning.Day(DateTime.Today),Tasks=new List<PlanTask>{new PlanTask {Id="t",Title="Test",Time=DateTime.Now.AddMinutes(25).ToString("HH:mm")}}},DateTime.Now,new Dictionary<string,DateTime>(),30,20).Count==1,"Le délai de rappel personnalisé s’applique");log.AppendLine("PASS compteurs sociaux persistés, jour distinct, réglages protégés, profil avec avatar, récurrence et délai des rappels.");w.Deactivate();timer.Stop();w.Close();File.WriteAllText(Path.Combine(directory,"tools-test.txt"),log.ToString());application.Shutdown();break;
   }}catch(Exception e){timer.Stop();File.WriteAllText(Path.Combine(directory,"tools-test.txt"),"FAIL stage "+stage+" "+e);w.Deactivate();if(worker!=null&&!worker.HasExited){File.WriteAllText(Path.Combine(directory,"worker.release"),"");worker.WaitForExit(3000);}w.Close();application.Shutdown(1);}};w.Loaded+=delegate{timer.Start();};return application.Run(w);
  }
 }
 partial class MainWindow {
  AppEntry toolsWorker;
  internal DependencyObject ToolsOverlay {get{return overlay;}}internal DependencyObject ToolsPage {get{return page;}}
  internal bool ToolsNotification {get{return reminder!=null;}}internal bool ToolsAdult {get{return preferences.AdultFilter;}}internal int ToolsHeld {get{return guard.HeldCount;}}
  internal void ToolsWorker(string dir,out Process p){toolsWorker=new AppEntry {Id="social-test",Name="Logiciel social de test",Target=Path.Combine(dir,"SeraphimTestWorker.exe"),Social=true};preferences.Apps.Add(toolsWorker);preferences.NativeContentLock=true;Session.Activate();guard.Activate();p=Process.Start(new ProcessStartInfo(toolsWorker.Target,"\""+Path.Combine(dir,"worker.release")+"\""){UseShellExecute=false,CreateNoWindow=true,WindowStyle=ProcessWindowStyle.Hidden});}
  internal void ToolsHold(){guard.Tick();if(guard.HeldCount!=1)throw new Exception("La pause du logiciel de test n'est pas effective.");}
  internal void ToolsExpire(){nativePasses[toolsWorker.Id]=DateTime.UtcNow.AddSeconds(-1);}
  internal void ToolsDualLayer(){toolsWorker.Work=true;preferences.SoftPlanning=true;ShowNativeGate(toolsWorker);PassageInput.Text=CurrentPassage.Text;PassageConfirm.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));if(guard.HeldCount!=1||CanLaunch(toolsWorker)||PreparationConfirm==null)throw new Exception("Un passage social ne doit pas contourner la checklist de travail.");toolsWorker.Work=false;}
  internal void ToolsCalendarEditor(){selectedDay=DateTime.Today;EditCalendar(null);}
  internal void ToolsCalendarTick(bool active){if(active)Session.Activate();else Session.Deactivate();ControlTick(DateTime.Now);}
  internal void ToolsNotificationCheck(string path){reminder.VerifyAndCapture(path);reminder.OpenButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));}
  internal void ToolsNotificationClose(){if(reminder!=null)reminder.Close();}
  internal void ToolsClockTick(){clockAnchor=DateTime.UtcNow.AddHours(-3).AddSeconds(-2);ControlTick(DateTime.Now);}
  internal void ToolsClockTickAgain(){ControlTick(DateTime.Now);}
  internal void ToolsUsageCheck(){AddUsage("social-instagram",65,DateTime.Today);AddUsage("social-instagram",55,DateTime.Today);AddUsage("social-instagram",30,DateTime.Today.AddDays(-1));SavePreferences();var saved=new PreferenceStore(store.FilePath).Load();if(TimeRules.Total(saved,"social-instagram",DateTime.Today)!=120||TimeRules.Total(saved,"social-instagram",DateTime.Today.AddDays(-1))!=30)throw new Exception("Les compteurs doivent être persistés par jour.");}
 }
}
